// Package conanfile parses Conan's dependency manifests — `conanfile.txt` and
// `conanfile.py` — to extract C/C++ dependencies.
//
// This is the file a Conan project COMMITS. `conan.lock` is generated by
// `conan install`, is frequently gitignored, and is absent from most
// repositories, so reading only the lockfile reads only the minority of Conan
// projects — they reported no dependencies at all.
//
// The lockfile remains the better source where both exist: it states resolved
// versions for the whole graph, while a manifest states the consumer's own
// declarations and may leave a version as a range.
package conanfile

import (
	"bufio"
	"io"
	"regexp"
	"strings"

	"go.mondoo.com/mql/providers/os/resources/languages"
	"go.mondoo.com/mql/providers/os/resources/languages/cpp"
)

var (
	_ languages.Extractor = (*Extractor)(nil)
	_ languages.Bom       = (*conanManifest)(nil)
)

// Extractor parses conanfile.txt and conanfile.py.
type Extractor struct{}

func (e *Extractor) Name() string { return "conanfile" }

// maxLines bounds the scan of a manifest. A conanfile.py is a Python program
// and is untrusted input; the declarations this reads all appear near the top
// of a real one, so a cap costs nothing and stops a pathological file.
const maxLines = 20000

func (e *Extractor) Parse(r io.Reader, filename string) (languages.Bom, error) {
	m := &conanManifest{}
	if filename != "" {
		m.evidence = append(m.evidence, filename)
	}

	if strings.HasSuffix(filename, ".py") {
		return m, m.parsePy(r)
	}
	return m, m.parseTxt(r)
}

// conanManifest holds the requirements a Conan manifest declares.
type conanManifest struct {
	requires []conanRequirement
	evidence []string
	seen     map[string]bool
}

type conanRequirement struct {
	ref   string
	scope string
}

// add records a requirement, ignoring a repeat of one already declared.
func (m *conanManifest) add(ref, scope string) {
	ref = strings.TrimSpace(ref)
	if ref == "" {
		return
	}
	if m.seen == nil {
		m.seen = map[string]bool{}
	}
	if m.seen[ref] {
		return
	}
	m.seen[ref] = true
	m.requires = append(m.requires, conanRequirement{ref: ref, scope: scope})
}

// txtSections maps a conanfile.txt section header to the scope its entries get.
// `tool_requires` (and its Conan 1 spelling `build_requires`) name tools that
// run during the build and are not linked into the artifact.
var txtSections = map[string]string{
	"requires":        languages.PackageScopeProd,
	"tool_requires":   languages.PackageScopeDev,
	"build_requires":  languages.PackageScopeDev,
	"test_requires":   languages.PackageScopeDev,
	"python_requires": languages.PackageScopeDev,
}

// parseTxt reads a conanfile.txt: an INI-shaped file whose `[requires]` section
// holds one reference per line.
func (m *conanManifest) parseTxt(r io.Reader) error {
	scanner := bufio.NewScanner(r)
	scope := ""
	for n := 0; scanner.Scan() && n < maxLines; n++ {
		line := strings.TrimSpace(scanner.Text())
		// A `#` starts a comment, and an inline one follows a reference.
		if idx := strings.IndexByte(line, '#'); idx >= 0 {
			line = strings.TrimSpace(line[:idx])
		}
		if line == "" {
			continue
		}
		if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
			// An unknown section ([generators], [options], [layout]) sets an
			// empty scope, which stops its entries being read as requirements.
			scope = txtSections[strings.ToLower(strings.Trim(line, "[]"))]
			continue
		}
		if scope == "" {
			continue
		}
		m.add(line, scope)
	}
	return scanner.Err()
}

// pyAttrRe matches a static requirements attribute and captures its assigned
// expression up to the end of the line:
//
//	requires = "zlib/1.3.1", "fmt/10.2.1"
//	tool_requires = ["cmake/3.28.1"]
//
// Deliberately anchored to an assignment at class-attribute indentation. A
// `self.requires(...)` call inside a requirements() method is NOT matched — see
// the package comment on why a computed requirement resolves to nothing.
var pyAttrRe = regexp.MustCompile(`^\s*(requires|tool_requires|build_requires|test_requires|python_requires)\s*=\s*(.+)$`)

// pyRefRe matches a quoted reference inside such an expression.
var pyRefRe = regexp.MustCompile(`["']([^"']+)["']`)

// pyScopes maps a conanfile.py attribute name to the scope its entries get.
var pyScopes = map[string]string{
	"requires":        languages.PackageScopeProd,
	"tool_requires":   languages.PackageScopeDev,
	"build_requires":  languages.PackageScopeDev,
	"test_requires":   languages.PackageScopeDev,
	"python_requires": languages.PackageScopeDev,
}

// parsePy reads the STATIC requirement attributes of a conanfile.py.
//
// A conanfile.py is a Python program, and a `requirements()` method may compute
// a reference from an option, a loop or the platform. Those resolve to NOTHING
// rather than to a guess: a version recovered from a partially evaluated Python
// expression is worse than an absent one, because it is a coordinate that looks
// resolved and matches the wrong advisories. Where a project builds its
// requirements dynamically, `conan.lock` is the source that can answer.
func (m *conanManifest) parsePy(r io.Reader) error {
	scanner := bufio.NewScanner(r)
	for n := 0; scanner.Scan() && n < maxLines; n++ {
		line := scanner.Text()
		if idx := strings.IndexByte(line, '#'); idx >= 0 {
			line = line[:idx]
		}
		match := pyAttrRe.FindStringSubmatch(line)
		if match == nil {
			continue
		}
		scope := pyScopes[match[1]]
		for _, ref := range pyRefRe.FindAllStringSubmatch(match[2], -1) {
			m.add(ref[1], scope)
		}
	}
	return scanner.Err()
}

// Root returns nil — a conanfile declares requirements, and a consumer manifest
// states no name or version of its own. (A recipe conanfile.py does carry
// `name`/`version` attributes, but a recipe describes the package being BUILT
// rather than a project being scanned.)
func (m *conanManifest) Root() *languages.Package { return nil }

// Direct returns the declared requirements. Everything a conanfile declares is
// direct by definition — it is the consumer's own requirement list.
func (m *conanManifest) Direct() languages.Packages {
	var packages languages.Packages
	for _, req := range m.requires {
		ref, ok := cpp.ParseConanRef(req.ref)
		if !ok {
			continue
		}
		packages = append(packages, &languages.Package{
			Name: ref.Name,
			// A manifest may state a range ("fmt/[>=9.0]") rather than a
			// version. A range is not a version, so it is reported as no
			// version at all; conan.lock is what resolves it.
			Version:      ref.ResolvedVersion(),
			Purl:         cpp.NewConanPackageUrl(ref),
			EvidenceList: cpp.NewEvidenceList(m.evidence),
			Scope:        req.scope,
		})
	}
	return packages
}

// Transitive returns nil — a conanfile declares only what the project itself
// requires. The closure is resolved at install time and lives in conan.lock.
func (m *conanManifest) Transitive() languages.Packages { return nil }
